use crate::support::{run, run_json};
use serde_json::Value as JsonValue;
use std::{ffi::OsStr, path::Path};
use unicodex_core::{decode_node, encode_value_node, Node, ObjectStore, RefStatus, Value};

pub(super) fn put_and_assert(cwd: &Path, residual: &str) -> String {
    let put = run_json(cwd, command("put", residual));
    assert_eq!(put["accepted"], true);
    assert_summary(&put["receipt"]);
    let cid = put["cid"].as_str().unwrap().to_owned();
    let store = ObjectStore::open(cwd);
    let value = load(&store, &cid);
    let forged = mutate(&store, &value, |entries| {
        *field_mut(entries, "execution_observation_outcome_failed_count") = Value::Int(0)
    });
    assert_eq!(store.verify_object(&forged).status, RefStatus::Ok);
    assert_unaccepted(cwd, &forged);
    let legacy = mutate(&store, &value, |entries| {
        *field_mut(entries, "schema") = Value::Text("fpm.authority_conflict_receipt.v1".to_owned());
        entries.retain(|(key, _)| !matches!(key, Value::Text(name) if name == "exact_execution_observation_outcome_summary_replayed" || name == "execution_observation_outcome_completed_count" || name == "execution_observation_outcome_failed_count"));
    });
    let verified = run_json(cwd, command("verify", &legacy));
    assert_eq!(verified["accepted"], true);
    assert_eq!(
        verified["receipt"]["schema"],
        "fpm.authority_conflict_receipt.v1"
    );
    assert_eq!(
        verified["receipt"]["exact_execution_observation_outcome_summary_replayed"],
        JsonValue::Null
    );
    cid
}

pub(super) fn assert_unaccepted(cwd: &Path, cid: &str) {
    assert_eq!(run(cwd, command("verify", cid)).status.code(), Some(2));
}
pub(super) fn assert_verified(cwd: &Path, cid: &str) {
    let output = run_json(cwd, command("verify", cid));
    assert_eq!(output["accepted"], true);
    assert_eq!(output["residual_receipt_accepted"], true);
    assert_summary(&output["receipt"]);
}
fn assert_summary(value: &JsonValue) {
    assert_eq!(value["schema"], "fpm.authority_conflict_receipt.v2");
    assert_eq!(
        value["exact_execution_observation_outcome_summary_replayed"],
        true
    );
    assert_eq!(value["execution_observation_outcome_completed_count"], 0);
    assert_eq!(value["execution_observation_outcome_failed_count"], 1);
    assert_eq!(value["conflict_analysis_executed"], false);
    assert_eq!(value["conflicts_empty_claimed"], false);
    assert_eq!(value["source_authority_migrated"], false);
}
fn command<'a>(op: &'a str, value: &'a str) -> [&'a OsStr; 7] {
    [
        OsStr::new("project"),
        OsStr::new("authority"),
        OsStr::new("conflict-receipt"),
        OsStr::new(op),
        OsStr::new(value),
        OsStr::new("--format"),
        OsStr::new("json"),
    ]
}
fn load(store: &ObjectStore, cid: &str) -> Value {
    let Node::Value(value) = decode_node(&store.get_canonical(cid).unwrap()).unwrap() else {
        panic!("conflict receipt must be value")
    };
    value
}
fn mutate<F: FnOnce(&mut Vec<(Value, Value)>)>(store: &ObjectStore, value: &Value, f: F) -> String {
    let Value::Map(mut entries) = value.clone() else {
        unreachable!()
    };
    f(&mut entries);
    store
        .put_canonical(&encode_value_node(&Value::Map(entries)).unwrap())
        .unwrap()
}
fn field_mut<'a>(entries: &'a mut [(Value, Value)], name: &str) -> &'a mut Value {
    &mut entries
        .iter_mut()
        .find(|(key, _)| key == &Value::Text(name.to_owned()))
        .unwrap()
        .1
}

